contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address proposedAddress, string memory typeStr) public payable {
        require(bytes(typeStr).length <= 32);
        uint beforeCount = c.proposalCount(); if (__ESBMC_reverted()) return;
        c.newAddressProposal(proposedAddress, typeStr); if (__ESBMC_reverted()) return;
        uint pid = c.proposalCount(); if (__ESBMC_reverted()) return;
        require(pid == beforeCount + 1);
        bool reverted;
        c.cancelProposal(pid, pid); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        require(c.mapPID_finalising(pid) == false);
        assert(reverted);
    }

    receive() external payable {}
}

