pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(address proposedAddress, string memory typeStr) internal {
        vm.assume(bytes(typeStr).length <= 32);
        uint256 beforeCount;
        try c.proposalCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        try c.newAddressProposal(proposedAddress, typeStr) {} catch { return; }
        uint256 pid;
        try c.proposalCount() returns (uint256 __r) { pid = __r; } catch { return; }
        vm.assume(pid == beforeCount + 1);
        bool reverted;
        try c.cancelProposal(pid, pid) { reverted = false; } catch { reverted = true; }
        vm.assume(c.mapPID_finalising(pid) == false);
        assertTrue(reverted);
    }

    function testFuzz_run(address proposedAddress, string memory typeStr) public {
